use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_sample_alert: Option<u8>,
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_sample_alert(container.api_sample_alert);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(sample_alert: Option<u8>)
{
  put_sample_alert(sample_alert);
}

/// getter for OUT EventDataPort
pub fn get_sample() -> Option<i32>
{
  return extern_api::OUT_sample.lock().unwrap_or_else(|e| e.into_inner()).clone()
}

/// setter for IN EventPort
pub fn put_sample_alert(value: Option<u8>)
{
  *extern_api::IN_sample_alert.lock().unwrap_or_else(|e| e.into_inner()) = value
}
